pm.test("Login page loads", () => pm.response.to.have.status(200));

// read the hidden CSRF field of the login form
const match = pm.response.text().match(/name="csrf_token" type="hidden" value="([^"]+)"/);
pm.test("CSRF token found", () => pm.expect(match).to.not.be.null);
pm.environment.set("csrf_token", match[1]);

pm.test("Logged in: dashboard is shown", () => {
    pm.response.to.have.status(200);
    pm.expect(pm.response.text()).to.include("Overview");
});

// after login, take the token from <meta name="csrf-token"> for the API calls
const match = pm.response.text().match(/<meta name="csrf-token" content="([^"]+)"/);
pm.environment.set("csrf_token", match[1]);

pm.test("Status 200", () => pm.response.to.have.status(200));
pm.test("Returns a list of categories", () => {
    const data = pm.response.json();
    pm.expect(data).to.be.an("array").that.is.not.empty;
    pm.expect(data[0]).to.have.keys("id", "name", "color", "icon");
});
